package com.playsphere.media;
import com.playsphere.common.Ids;import jakarta.persistence.*;import java.time.Instant;
@Entity @Table(name="media_assets") public class MediaAsset{
 @Id @Column(length=36) private String id;@Column(name="owner_user_id",nullable=false,length=36) private String ownerUserId;@Column(name="public_id",nullable=false,length=255) private String publicId;@Column(name="secure_url",nullable=false,length=700) private String secureUrl;@Column(name="resource_type",nullable=false,length=32) private String resourceType;@Column(name="original_filename",length=255) private String originalFilename;@Column(name="content_type",length=100) private String contentType;@Column(name="size_bytes",nullable=false) private long sizeBytes;@Column(name="storage_provider",nullable=false,length=32) private String storageProvider;@Column(name="created_at",nullable=false) private Instant createdAt;
 protected MediaAsset(){}public MediaAsset(String owner,StoredMedia m,String filename,String contentType,long size){id=Ids.uuid();ownerUserId=owner;publicId=m.publicId();secureUrl=m.secureUrl();resourceType="IMAGE";originalFilename=filename;this.contentType=contentType;sizeBytes=size;storageProvider=m.provider();createdAt=Instant.now();}
 public String getId(){return id;}public String getOwnerUserId(){return ownerUserId;}public String getPublicId(){return publicId;}public String getSecureUrl(){return secureUrl;}public String getResourceType(){return resourceType;}public String getOriginalFilename(){return originalFilename;}public String getContentType(){return contentType;}public long getSizeBytes(){return sizeBytes;}public String getStorageProvider(){return storageProvider;}public Instant getCreatedAt(){return createdAt;}
}
